mapper.select:
SELECT DISTINCT id, cientity_id AS ciEntityId, attr_id AS attrId, type, invoke_id AS invokeId FROM cmdb_invokeentity
WHERE invoke_id IN
#{invokeId}
AND attr_id IN
#{attrId}
WHERE 1 = 0

mapper.delete:
